<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api } from '@/services/api'
const props=withDefaults(defineProps<{limit?:number;featuredOnly?:boolean;editing?:boolean}>(),{limit:6,featuredOnly:false,editing:false})
const rows=ref<any[]>([]);const loading=ref(false)
const visible=computed(()=>rows.value.filter(row=>!props.featuredOnly||row.featured).slice(0,Math.max(1,props.limit)))
onMounted(async()=>{if(props.editing)return;loading.value=true;try{const page=await api<any>('/api/public/academy/courses?size=100');rows.value=page.content||[]}finally{loading.value=false}})
</script>
<template><section class="academy-block"><div v-if="editing" class="preview"><b>Catálogo de TrastAcademy</b><span>{{ limit }} cursos{{ featuredOnly?' destacados':'' }}</span></div><p v-else-if="loading">Cargando cursos…</p><div v-else class="grid"><RouterLink v-for="course in visible" :key="course.id" :to="`/academy/${course.slug}`"><div class="cover" :style="course.featuredImageUrl?{backgroundImage:`url(${course.featuredImageUrl})`}:{}"/><small>{{ course.instructorName||'Academy' }}</small><h3>{{ course.title }}</h3><p>{{ course.excerpt }}</p><strong>{{ course.accessType==='FREE'?'Gratis':`${course.currency} ${course.price}` }}</strong></RouterLink></div></section></template>
<style scoped>.academy-block{width:100%}.preview{border:1px dashed var(--border,#cbd5e1);border-radius:1rem;padding:2rem;display:grid;gap:.4rem;text-align:center}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.2rem}.grid a{color:inherit;text-decoration:none;border:1px solid var(--border,#e5e7eb);border-radius:1rem;overflow:hidden;padding-bottom:1rem;background:var(--surface,#fff)}.cover{aspect-ratio:16/9;background:linear-gradient(135deg,var(--primary,#5b4ee8),#111827);background-size:cover;background-position:center}.grid h3,.grid p,.grid small,.grid strong{display:block;margin:.65rem 1rem 0}.grid small,.grid p{color:var(--muted,#64748b)}.grid p{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.grid{grid-template-columns:1fr}}</style>
